/// v0.1.769: terminal re-parse defer policy (pure, so it's unit-testable; the
/// live frame driver only computes the inputs and acts on the bool).
///
/// The terminal reader renders finished snapshots off-thread; the UI poll
/// decides whether to fire the EXPENSIVE RichText re-parse for a new snapshot or
/// to DEFER it so a burst (helix open, pager page) coalesces into one re-parse.
/// The decision is nuanced rather than "any multi-frame jump → defer":
///   - a single-frame delta (typing) never defers — stays instant;
///   - the LEADING EDGE of a burst (the screen has been quiescent for
///     `leading_edge_ms`) renders immediately, so an app opening from idle
///     paints right away instead of waiting out the coalescing window — this is
///     the helix-load latency the coarse policy added;
///   - only a SUSTAINED storm (recent render + still multi-frame) coalesces, and
///     only up to `max_defer` consecutive polls so a continuous stream (build
///     log) still updates steadily rather than starving.
fn should_defer_reparse(
    gen_delta: u64,
    defer_count: u32,
    ms_since_render: u128,
    leading_edge_ms: u128,
    max_defer: u32,
) -> bool {
    if gen_delta <= 1 {
        return false; // typing / single new frame → never defer
    }
    if ms_since_render >= leading_edge_ms {
        return false; // leading edge after idle → render now (catch app load)
    }
    defer_count < max_defer // sustained storm → coalesce, capped
}

#[cfg(test)]
mod defer_policy_tests {
    use super::should_defer_reparse;
    const LE: u128 = 80;
    const MAX: u32 = 3;

    #[test]
    fn typing_never_defers() {
        // single-frame delta is always instant regardless of timing/count
        assert!(!should_defer_reparse(1, 0, 0, LE, MAX));
        assert!(!should_defer_reparse(1, 2, 5, LE, MAX));
        assert!(!should_defer_reparse(0, 0, 0, LE, MAX));
    }

    #[test]
    fn leading_edge_of_burst_renders_immediately() {
        // app opening from idle: big multi-frame jump but the screen has been
        // quiescent → render now, do NOT wait out the coalescing window.
        assert!(!should_defer_reparse(20, 0, 500, LE, MAX), "helix load must not defer");
        assert!(!should_defer_reparse(8, 0, LE, LE, MAX), "exactly at threshold renders");
    }

    #[test]
    fn sustained_storm_coalesces_then_caps() {
        // recent render + still bursting → coalesce while under the cap...
        assert!(should_defer_reparse(5, 0, 10, LE, MAX));
        assert!(should_defer_reparse(5, 2, 10, LE, MAX));
        // ...but the cap forces a render so a continuous stream never starves.
        assert!(!should_defer_reparse(5, MAX, 10, LE, MAX));
        assert!(!should_defer_reparse(5, MAX + 1, 10, LE, MAX));
    }

    #[test]
    fn leading_edge_beats_the_cap_counter() {
        // even with defer_count high, a stale screen renders immediately —
        // staleness (load latency) takes precedence over the storm counter.
        assert!(!should_defer_reparse(9, 2, 1000, LE, MAX));
    }
}
